export type LocalizedText = { fr: string; en: string };
export type OrganizationalGapMapping = {
  gapCode: string;
  gap: string;
  remediation: string;
};
export type OrganizationalQuestion = {
  id: string;
  type: OrganizationalQuestionType;
  conditionKey: OrganizationalContextKey | null;
  question: LocalizedText;
  evidence?: string;
  partial: OrganizationalGapMapping;
  absent: OrganizationalGapMapping;
};
export type OrganizationalQuickContext = {
  key: OrganizationalContextKey;
  conditionKey?: OrganizationalContextKey | null;
  question: LocalizedText;
};
export type OrganizationalControl = {
  id: string;
  code: string;
  name: string;
  applicability: string;
  applicabilityKey: OrganizationalContextKey | null;
  questions: readonly OrganizationalQuestion[];
  quickContext: readonly OrganizationalQuickContext[];
};

const question = (
  id: string,
  type: OrganizationalQuestionType,
  fr: string,
  en: string,
  evidence: string | undefined,
  partialGapCode: string,
  partialGap: string,
  partialRemediation: string,
  absentGapCode: string,
  absentGap: string,
  absentRemediation: string,
  conditionKey: OrganizationalContextKey | null = null,
): OrganizationalQuestion => ({
  id,
  type,
  conditionKey,
  question: { fr, en },
  ...(evidence ? { evidence } : {}),
  partial: { gapCode: partialGapCode, gap: partialGap, remediation: partialRemediation },
  absent: { gapCode: absentGapCode, gap: absentGap, remediation: absentRemediation },
});

const batchQuestion = (
  id: string,
  type: OrganizationalQuestionType,
  fr: string,
  en: string,
  evidence: string | undefined,
  gapFamily: string,
  partialRemediation: string,
  absentRemediation: string,
  conditionKey: OrganizationalContextKey | null = null,
) => question(
  id,
  type,
  fr,
  en,
  evidence,
  `${gapFamily}_PARTIAL`,
  partialRemediation,
  partialRemediation,
  `${gapFamily}_ABSENT`,
  absentRemediation,
  absentRemediation,
  conditionKey,
);

